import sys

def main():
    import sys
    input = sys.stdin.read
    data = input().splitlines()

    N = int(data[0])
    results = []

    for i in range(1, N + 1):
        command = data[i].strip()
        if command.startswith("Simon says"):
            results.append(command[len("Simon says"):].strip())

    for result in results:
        print(result)

if __name__ == "__main__":
    main()
